{{-- One location: $l is the row being edited, or null for a new one; $sfx keeps ids unique. --}}
<div class="ix-form__row"><label class="ix-label" for="l_label_{{ $sfx }}">Name</label><input class="ix-input" id="l_label_{{ $sfx }}" name="label" minlength="2" maxlength="80" required value="{{ $l ? $l->label : old('label') }}" placeholder="For example: Head office, Workshop, Mbombela branch"></div>
<div class="ix-form__row"><label class="ix-label" for="l_addr_{{ $sfx }}">Street address <span class="ix-hint">optional</span></label><input class="ix-input" id="l_addr_{{ $sfx }}" name="address" maxlength="255" value="{{ $l ? $l->address : old('address') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="l_city_{{ $sfx }}">Town or city</label><input class="ix-input" id="l_city_{{ $sfx }}" name="city" minlength="2" maxlength="80" required value="{{ $l ? $l->city : old('city') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="l_prov_{{ $sfx }}">Province <span class="ix-hint">optional</span></label><input class="ix-input" id="l_prov_{{ $sfx }}" name="province" maxlength="80" value="{{ $l ? $l->province : old('province') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="l_code_{{ $sfx }}">Postal code <span class="ix-hint">optional</span></label><input class="ix-input" id="l_code_{{ $sfx }}" name="postal_code" maxlength="12" value="{{ $l ? $l->postal_code : old('postal_code') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="l_country_{{ $sfx }}">Country <span class="ix-hint">optional</span></label><input class="ix-input" id="l_country_{{ $sfx }}" name="country" maxlength="60" value="{{ $l ? $l->country : old('country', 'South Africa') }}"></div>
<input type="hidden" name="show_address" value="0">
<label class="ix-choice__chk"><input type="checkbox" name="show_address" value="1" @checked($l ? $l->show_address : old('show_address'))> Show the street address on the page, with directions</label>
